package com.example.orders.entity;import javax.persistence.*;import java.math.BigDecimal;import java.util.Date;@Entity @Table(name="orders") public class OrderEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String name;@Column(name="customer_id",nullable=false)private String customerId;@Column(name="product_type",nullable=false)private String productType;private Integer quantity;@Column(precision=19,scale=2)private BigDecimal price;@Temporal(TemporalType.TIMESTAMP)@Column(name="order_date")private Date orderDate;public Long getId(){return id;}public void setId(Long v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getCustomerId(){return customerId;}public void setCustomerId(String v){customerId=v;}public String getProductType(){return productType;}public void setProductType(String v){productType=v;}public Integer getQuantity(){return quantity;}public void setQuantity(Integer v){quantity=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public Date getOrderDate(){return orderDate;}public void setOrderDate(Date v){orderDate=v;}}